-- Draft of scoped item variants. Review original ownership, affixes and effects before promotion.
CREATE TEMPORARY TABLE `_coa_tbc_keystone_gear` (
    `source` INT UNSIGNED NOT NULL,
    `target` INT UNSIGNED PRIMARY KEY,
    `depth` TINYINT UNSIGNED NOT NULL,
    `Quality` INT NOT NULL,
    `ItemLevel` INT NOT NULL,
    `RequiredLevel` INT NOT NULL,
    `armor` INT NOT NULL,
    `block` INT NOT NULL,
    `socketBonus` INT NOT NULL,
    `stat_value1` INT NOT NULL,
