DELETE FROM `coa_dungeon_rescale_item` WHERE `entry` IN (SELECT `target` FROM `_coa_tbc_keystone_gear`);

DELETE FROM `item_dbc` WHERE `ID` IN (SELECT `target` FROM `_coa_tbc_keystone_gear`);
SELECT `item`.`entry`, `item`.`class`, `item`.`subclass`, `item`.`SoundOverrideSubclass`, `item`.`Material`,
    `item`.`displayid`, `item`.`InventoryType`, `item`.`sheath`
FROM `item_template` AS `item` JOIN `_coa_tbc_keystone_gear` AS `budget` ON `budget`.`target` = `item`.`entry`;
DROP TEMPORARY TABLE `_coa_tbc_keystone_gear`;
